<?php require_once __DIR__.'/includes/functions.php';if(current_user())redirect('dashboard.php');$errors=[];$name='';$email='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$name=trim((string)($_POST['name']??''));$email=strtolower(trim((string)($_POST['email']??'')));$pass=(string)($_POST['password']??'');if(!valid_name($name))$errors[]='Name must be 2–100 characters.';if(!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($email)>190)$errors[]='Enter a valid email address.';if(!valid_password($pass))$errors[]='Password must be 8–72 characters.';if($pass!==($_POST['confirm']??''))$errors[]='Passwords do not match.';if(!$errors){try{$stmt=db()->prepare('INSERT INTO users (name,email,password_hash,role_id) VALUES (?,?,?,2)');$stmt->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT)]);session_regenerate_id(true);$_SESSION['uid']=(int)db()->lastInsertId();flash('success','Welcome! Your account is ready.');redirect('dashboard.php');}catch(PDOException $ex){if($ex->getCode()==='23000')$errors[]='Email is already registered.';else throw $ex;}}}page_start('Create account');?>
<section class="auth-wrap"><div class="hero"><span class="eyebrow">JOIN USERHUB</span><h1>Start something <em>great.</em></h1><p>Create your account to manage your profile and explore your personal dashboard.</p><div class="glow"></div></div><div class="panel auth-panel"><h2>Create account</h2><p class="muted">Already a member? <a href="<?=e(url('login.php'))?>">Sign in</a></p><?php foreach($errors as $err):?><div class="alert error"><?=e($err)?></div><?php endforeach;?><form method="post" class="stack"><?=csrf_field()?><label>Full name<input name="name" maxlength="100" minlength="2" autocomplete="name" required value="<?=e($name)?>" placeholder="Alex Morgan"></label><label>Email address<input type="email" name="email" autocomplete="email" required value="<?=e($email)?>" placeholder="alex@example.com"></label><label>Password<input type="password" name="password" autocomplete="new-password" minlength="8" maxlength="72" required placeholder="At least 8 characters"></label><label>Confirm password<input type="password" name="confirm" autocomplete="new-password" required placeholder="Repeat your password"></label><button class="button" type="submit">Create account →</button></form></div></section><?php page_end(); ?>
